//! Causal projection/join kernel extracted from archived src/policy.rs.
//! Stamp is supplied by the CRR adapter; this crate allocates no clocks.
use crate::{
    Error, Result,
    model::{Value, decode, encode},
};
use murmur_tx::policies::Causal;
use serde::{Deserialize, Serialize};

/// Archived policy state with host-supplied native CRR event tokens.
///
/// Stamp must express the host's accepted control/baseline event ordering.
/// It must not be generated by a second logical clock. generation and scope
/// are the native row incarnation (CRR causal length), supplied by the host.
/// This adapted type is not an archive wire-compatible persistence format.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct State<Stamp> {
    pub version: Stamp,
    pub domain: [u8; 16],
    pub branch: Stamp,
    pub scope: u64,
    pub baseline: Value,
    pub basis: Stamp,
    pub table: String,
    pub column: String,
    pub key: Vec<Value>,
    pub generation: u64,
    pub causal: Causal,
}

pub fn projection<Stamp>(state: &State<Stamp>) -> Result<Value> {
    match &state.causal {
        Causal::Counter(c) => {
            let base = match state.baseline {
                Value::Integer(n) => n,
                _ => return Err(Error::Corrupt("counter baseline".into())),
            };
            Ok(Value::Integer(
                i64::try_from(
                    base as i128 + c.positive.values().map(|n| *n as i128).sum::<i128>()
                        - c.negative.values().map(|n| *n as i128).sum::<i128>(),
                )
                .map_err(|_| Error::Limit("counter projection overflow".into()))?,
            ))
        }
        Causal::Set(s) => {
            let values = s
                .values()
                .iter()
                .map(|b| decode::<Value>(b))
                .collect::<Result<Vec<_>>>()?;
            Ok(Value::Blob(encode(&values)?))
        }
    }
}

/// Join a losing-incarnation state into the winning row's state. The winner
/// keeps its baseline (its incarnation won the row merge); the orphan's seed
/// tags never survive a baseline takeover. Scopes must match and the orphan
/// basis must not exceed the winner's, otherwise the orphan stays carried
/// but unprojected (false).
pub fn rebase_orphan<Stamp: Clone + Ord>(
    winner: &mut State<Stamp>,
    orphan: &State<Stamp>,
) -> Result<bool> {
    if (orphan.domain, &orphan.branch) != (winner.domain, &winner.branch)
        || orphan.basis > winner.basis
    {
        return Ok(false);
    }
    let mut source = orphan.clone();
    if source.baseline != winner.baseline {
        if let Causal::Set(set) = &mut source.causal {
            for tags in set.additions.values_mut() {
                tags.retain(|t| t.node != [0; 16]);
            }
        }
        source.baseline = winner.baseline.clone();
    }
    join_state(winner, &source)?;
    Ok(true)
}

pub fn join_state<Stamp: Clone + Ord>(
    target: &mut State<Stamp>,
    source: &State<Stamp>,
) -> Result<()> {
    target.version = target.version.clone().max(source.version.clone());
    let mut source = source.clone();
    if source.basis > target.basis {
        if let Causal::Set(set) = &mut target.causal {
            for tags in set.additions.values_mut() {
                tags.retain(|t| t.node != [0; 16]);
            }
        }
        target.baseline = source.baseline.clone();
        target.basis = source.basis;
    } else if source.basis < target.basis {
        if let Causal::Set(set) = &mut source.causal {
            for tags in set.additions.values_mut() {
                tags.retain(|t| t.node != [0; 16]);
            }
        }
    } else if source.baseline != target.baseline {
        return Err(Error::Corrupt(
            "different causal baselines for one identity".into(),
        ));
    }
    target
        .causal
        .join(&source.causal)
        .map_err(|e| Error::Corrupt(e.to_string()))
}
